(x, y, t) => {
  const cx = 240, cy = 120;
  const wx = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10 + Math.sin((x+y)*0.01+t*0.15)*8;
  const wy = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10 + Math.cos((x-y)*0.012-t*0.18)*8;
  const sx = x+wx, sy = y+wy;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.2],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*60, 40+Math.cos(t*0.65+1)*40, 0.14, 1.3, 0.7],
    [400+Math.cos(t*0.55+2)*70, 200+Math.sin(t*0.75)*50, 0.05, 2.8, 1.15]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wave = Math.sin(d*f-t*sp);
    const wave2 = Math.sin(d*f*0.7+t*sp*0.6+1.5);
    const harm = Math.sin(d*f*1.3-t*sp*0.8+0.7)*0.4;
    aS += (wave+harm)*w;
    iS += (wave2+Math.sin(d*f*0.5-t*sp*0.4+2.1)*0.3)*w;
    cS += Math.sin(d*f*0.3+t*sp*0.3)*w*0.5;
  }
  const n = src.length, act=aS/n, inh=iS/n, cor=cS/n;
  const bg1 = Math.sin(sx*0.04+sy*0.025+t*0.8);
  const bg2 = Math.sin(sx*0.03-sy*0.04+t*1.1);
  const bg3 = Math.sin((sx+sy)*0.12+t*2.5)*0.2;
  const bg4 = Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg5 = Math.sin(sx*0.07*Math.cos(t*0.1)+sy*0.05*Math.sin(t*0.15)+t*0.6)*0.15;
  const bg = (bg1+bg2)/2+bg3+bg4+bg5;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const sp1 = Math.sin(dist*0.05-ang*3-t*1.5);
  const sp2 = Math.sin(dist*0.04+ang*4-t*1.2);
  const sp3 = Math.sin(dist*0.08-ang*2+t*0.9)*0.3;
  const spiral = (sp1+sp2)*0.4+sp3;
  const lap = Math.sin(sx*0.22)*Math.sin(sy*0.22)+Math.sin(sx*0.15+sy*0.15+t)*0.4+Math.sin(sx*0.3-t*0.5)*Math.cos(sy*0.25+t*0.3)*0.2;
  const feed = act*1.2 - inh*0.8 + bg*0.25 + spiral*0.6 + cor*0.4;
  const kill = inh*0.6 - act*0.3 + lap*0.15;
  const reaction = Math.tanh(feed*2.0 - kill*1.5);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(sx*0.08-t*0.3)*Math.sin(sy*0.12+t*0.4)*0.3)*1.5)*0.25;
  const ripple = Math.sin(dist*0.15-t*3)*Math.exp(-dist*0.008)*0.2*(0.5+0.5*Math.sin(t*0.5));
  const blend = reaction*0.6+cell*0.2+ripple*0.2;
  const v = blend*0.5+0.5;
  const detail = Math.sin(sx*0.4+t*2)*Math.sin(sy*0.35-t*1.7)*0.06;
  const fv = Math.max(0, Math.min(1, v+detail));
  const pal = [
    [5,12,52],[8,32,82],[12,60,108],[18,95,128],[25,135,138],
    [50,168,128],[110,185,105],[175,190,75],[210,170,55],
    [220,135,60],[210,95,65],[185,60,68],[140,38,62],[95,22,55],[50,14,48],[5,12,52]
  ];
  const idx = fv*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const sf = f*f*(3-2*f);
  const lum = 0.85+Math.sin(reaction*Math.PI)*0.15;
  const edge = Math.abs(reaction)>0.65?1.12:Math.abs(reaction)>0.85?1.25:1.0;
  const glow = Math.max(0, reaction)*0.08;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum*edge+glow*80))|0,
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum*edge+glow*120))|0,
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum*edge+glow*180))|0
  ];
}
